<script setup>
import { computed, nextTick, provide, ref, toRef, watch } from 'vue';
import { readDraft } from '../workbench/draftStore.js';
import { restoreStrategyDraft, strategyHandoffKey } from '../app-workshop/handoff.js';
import { LANGUAGE_STYLE_KEY, dataMessage, languageStyleLabel } from './language.js';
import { describeRulePlan, templateRules } from './ruleLanguage.js';
import WorkshopChart from './WorkshopChart.vue';
import WorkshopConversation from './WorkshopConversation.vue';
import { useStrategyWorkshop } from './useStrategyWorkshop.js';
import { dateTime, interval, isFinishedRun, lines, metricCards, money, number, statusLabel } from './format.js';

const props = defineProps({ ownerKey: { type: [String, Number], required: true }, personalAppId: { type: String, default: '' } });
const emit = defineEmits(['saved', 'new-session']);
const w = useStrategyWorkshop(toRef(props, 'ownerKey'), toRef(props, 'personalAppId'));
const { languageStyle, idea, session, capabilities, catalog, symbols, form, fieldErrors, error, syncError, busy, loading, step,
  preflight, coverageAccepted, diagnosticAccepted, run, history, nextCursor, historyOpen, historyReadOnly, conversation, conversationOpen,
  historicalCode, candidate, customization, customizationInstructions, report, active, formalAvailable, coverageRequired, canRun, selectedSymbol, sourceRunId, personalApp, personalAppView, personalAppSaveError, canSavePersonalApp, canReconfigurePersonalApp } = w;
provide(LANGUAGE_STYLE_KEY, languageStyle);
const say = (beginner, expert) => languageStyle.value === 'expert' ? expert : beginner;
const root = ref(null);
const codeStatus = ref('');
const incomingHandoff = ref(readDraft(strategyHandoffKey(props.ownerKey)));
async function restorePreviousStrategyDraft() { if (restoreStrategyDraft(props.ownerKey)) { incomingHandoff.value = null; await w.reload(); } }
const viewingHistory = computed(() => historyOpen.value || conversationOpen.value || (historyReadOnly.value && !personalAppView.value));
const sessionStatus = (value) => ({ awaiting_selection: '等待确认策略', customizing: '正在整理自定义规则', awaiting_custom_selection: '等待采用自定义策略', configuring: '设置回测中', ready: '等待发起回测', needs_clarification: '等待补充规则', unsupported_data: '缺少额外数据', rules_ready: '等待确认规则', validated: '代码校验通过', validation_failed: '代码校验未通过', completed: '已有回测结果' }[value] || statusLabel(value));
const activeStep = computed(() => ({ idea: 0, recommendation: 1, customization: 1, config: 2, result: 3 }[step.value] || 0));
const steps = computed(() => languageStyle.value === 'expert' ? ['策略假设', '规则确认', '回测配置', '绩效评估'] : ['说说想法', '选好规则', '用历史数据试试', '看看结果']);
const strategy = computed(() => candidate.value?.strategy || candidate.value || run.value?.strategy || {});
const catalogStrategy = computed(() => catalog.value.find((value) => value.strategyId === candidate.value?.strategyId) || {});
const selectionAccepted = computed(() => session.value?.selectionApproval?.decision === 'accept');
const name = computed(() => strategy.value.name || candidate.value?.strategyName || candidate.value?.name || run.value?.strategy?.name || '固定策略');
const version = computed(() => strategy.value.version || candidate.value?.version || '');
const explanation = computed(() => candidate.value?.explanation || {});
const understoodIdea = computed(() => typeof explanation.value === 'object' ? explanation.value.understoodIdea || '' : '');
const implementationApproach = computed(() => typeof explanation.value === 'object' ? explanation.value.implementationApproach || '' : '');
const rationale = computed(() => typeof explanation.value === 'string' ? explanation.value : explanation.value.whyThisStrategy || explanation.value.rationale || candidate.value?.rationale || candidate.value?.why || candidate.value?.summary || '');
const rules = computed(() => {
  const original = lines(catalogStrategy.value.rules || strategy.value.rules || candidate.value?.rules || strategy.value.summary);
  return historyReadOnly.value ? original : templateRules(candidate.value?.strategyId, languageStyle.value, original);
});
const covered = computed(() => lines(explanation.value.coveredParts || explanation.value.matchedRules || candidate.value?.matchedRules));
const gaps = computed(() => lines(explanation.value.uncoveredParts || explanation.value.uncoveredRules || candidate.value?.uncoveredRules || candidate.value?.gaps || candidate.value?.differences));
const fallbackText = computed(() => candidate.value?.fallbackReason === 'model_unavailable' ? say('分析服务暂时不可用。先给你一个比较最近两段平均价格的示例（双均线），但它还没有按你的想法完成匹配。', '语义匹配服务暂不可用，当前返回已校验的双均线基线模板，尚未确认其覆盖用户策略假设。') : say('这段话里还看不出明确的买卖规则。先给你一个比较最近两段平均价格的示例（双均线），它并没有完整实现你的想法。', '当前输入不足以提取可执行交易规则，返回双均线基线模板；该模板不代表完整覆盖用户假设。'));
const fixedParameters = computed(() => candidate.value?.parameters || strategy.value.parameters || report.value?.strategy?.parameters || {});
const sourceCode = computed(() => step.value === 'result' ? historicalCode.value : step.value === 'customization' ? customization.value?.sourceCode || '' : candidate.value?.sourceCode || strategy.value.sourceCode || '');
const customStatus = computed(() => ({ needs_clarification: '需要补充规则', unsupported_data: '需要额外数据', rules_ready: '等待确认规则', validation_failed: '代码校验未通过', validated: '代码校验通过' }[customization.value?.status] || '准备整理规则'));
const customSummary = computed(() => Object.entries(describeRulePlan(customization.value?.rulePlan, languageStyle.value, customization.value?.ruleSummary || {})).map(([key, value]) => ({ key, label: ({ entry: '买入条件', exit: say('卖出条件', '退出条件'), name: '策略名称', summary: '策略说明', warmup_bars: say('先准备多少天数据', '指标预热'), required_features: '额外数据', semantics: say('具体怎么做', '执行规则') }[key] || key), value: key === 'warmup_bars' ? say(`${value} 个交易日`, `${value} 根日线`) : key === 'required_features' && !value?.length ? say('已有数据就够用', '无需外源数据') : Array.isArray(value) ? value.join('；') : typeof value === 'object' ? JSON.stringify(value) : String(value) })));
const customizationError = computed(() => customization.value?.error?.message || customization.value?.error || customization.value?.validation?.message || customization.value?.validation?.error || '本版本尚未通过校验，请修改描述后重新生成规则。');
const diagnostic = computed(() => run.value?.mode === 'diagnostic' || report.value?.report_eligible === false);
const metrics = computed(() => metricCards(report.value, languageStyle.value));
const missingData = computed(() => lines(preflight.value?.gate?.reasons || preflight.value?.gate?.missing || preflight.value?.gate?.missingCapabilities || preflight.value?.gate?.issues).map((message) => dataMessage(message, languageStyle.value)));
const coverageReasons = computed(() => lines(preflight.value?.coverage?.reasons).map((message) => dataMessage(message, languageStyle.value)));
const warnings = computed(() => lines(report.value?.warnings).map((message) => dataMessage(message, languageStyle.value)));
const position = computed(() => report.value?.strategy_result?.open_position);
const fills = computed(() => report.value?.strategy_result?.fills || []);
const trades = computed(() => report.value?.strategy_result?.closed_trades || []);
const rejectedOrders = computed(() => report.value?.strategy_result?.rejected_orders || []);
const runError = computed(() => typeof run.value?.error === 'string' ? run.value.error : run.value?.error?.message || '本次运行未产生完整结果。');
const asof = computed(() => run.value?.asof || run.value?.gate?.asof || report.value?.provenance?.asof || preflight.value?.asof || selectedSymbol.value?.asof || capabilities.value?.defaults?.endDate || '待数据校验');
const phase = computed(() => ({ validating: say('正在检查数据', '正在校验数据'), loading_data: say('正在读取历史价格', '正在载入行情'), generating_signals: say('正在判断何时买卖', '正在生成交易信号'), simulating: say('正在按规则模拟买卖', '正在执行模拟撮合'), calculating: say('正在计算赚亏和波动', '正在计算绩效指标'), queued: say('正在排队，请稍等', '等待可用运行位置') }[run.value?.phase] || run.value?.phase || statusLabel(run.value?.status)));
const runIdea = computed(() => run.value?.idea || run.value?.candidate?.idea || session.value?.idea || idea.value);
const customRun = computed(() => run.value?.candidate?.strategyKind === 'custom' || Boolean(report.value?.custom_strategy));
const customRunEvidence = computed(() => report.value?.custom_strategy || {});
const customRunRules = computed(() => run.value?.candidate?.ruleSummary || {});
const customRunTrace = computed(() => ({
  originalIdea: customRunEvidence.value.original_idea || run.value?.customizationProvenance?.originalIdea,
  clarifications: customRunEvidence.value.clarifications || run.value?.customizationProvenance?.clarifications,
  baseStrategy: customRunEvidence.value.base_strategy || run.value?.customizationProvenance?.baseStrategy,
  ruleApproval: customRunEvidence.value.rule_approval,
  skillVersion: customRunEvidence.value.skill_version,
  runtimeHash: customRunEvidence.value.runtime_sha256,
  validation: customRunEvidence.value.validation,
}));

watch(() => step.value, async () => {
  codeStatus.value = '';
  await nextTick();
  root.value?.querySelector('[data-step-heading]')?.focus({ preventScroll: true });
});
watch(fieldErrors, async () => {
  if (!Object.keys(fieldErrors.value).length) return;
  await nextTick();
  root.value?.querySelector('[aria-invalid="true"]')?.focus();
});
watch(() => customization.value?.id, () => { codeStatus.value = ''; });
watch(conversationOpen, async (opened) => { if (opened) { await nextTick(); root.value?.querySelector('.sw-conversation [data-step-heading]')?.focus({ preventScroll: true }); } });

async function copyCode() {
  try {
    await navigator.clipboard.writeText(sourceCode.value);
    codeStatus.value = '已复制完整策略模块。';
  } catch {
    codeStatus.value = '浏览器未允许剪贴板访问，请在代码区域选择文本后复制。';
    await nextTick();
    root.value?.querySelector('.sw-code pre')?.focus();
  }
}

async function addPersonalApp() {
  const app = await w.savePersonalApp();
  if (app) emit('saved', app);
}

function startNewSession(options = {}) {
  w.newSession(options);
  emit('new-session');
}

function backToParameters() {
  if (historyReadOnly.value) return;
  step.value = 'config';
  w.resetPreflight();
}

function viewConfirmedStrategy() {
  step.value = customization.value?.status === 'validated' ? 'customization' : 'recommendation';
}

function openCode(event) {
  if (event.target.open && step.value === 'result') w.getHistoricalCode();
}

const rejectReason = (reason) => ({
  position_not_settled: '持仓尚未达到可卖出时间', insufficient_cash_for_minimum_lot: '资金不足最小交易单位',
  suspended_or_no_volume: '停牌或无成交量', suspended: '停牌', zero_volume: '无成交量',
  open_at_upper_limit: '开盘涨停，未买入', open_at_lower_limit: '开盘跌停，未卖出',
  slipped_price_above_upper_limit: '滑点后价格超过涨停价', slipped_price_below_lower_limit: '滑点后价格低于跌停价',
}[reason] || reason);
</script>

<template>
  <div ref="root" class="strategy-workshop" :data-language-style="languageStyle">
    <div v-if="incomingHandoff && step === 'idea' && !session && !historyOpen && !conversationOpen" class="sw-notice" data-strategy-handoff><p>已带上你在应用工坊提出的问题，作为一个新的策略草稿。检查后再开始分析，之前的历史记录仍然保留。</p><button v-if="incomingHandoff.previous" type="button" class="secondary-button" data-action="restore-strategy-draft" :disabled="Boolean(busy) || loading" @click="restorePreviousStrategyDraft">恢复之前的策略草稿</button></div>
    <div class="sw-language-bar">
      <div class="sw-language-switch" role="group" aria-label="语言风格">
        <button type="button" :aria-pressed="languageStyle === 'beginner'" @click="w.setLanguageStyle('beginner')">小白模式</button>
        <button type="button" :aria-pressed="languageStyle === 'expert'" @click="w.setLanguageStyle('expert')">专家模式</button>
      </div>
      <p class="sw-language-hint">{{ say('页面说明和后续回复用大白话。已经生成的内容保留原文。', '页面说明与后续回复使用金融量化术语；已生成内容保留原文。') }}</p>
    </div>
    <header class="sw-header">
      <div><p class="sw-eyebrow">AI STRATEGY WORKSHOP</p><h1>{{ personalAppView && personalApp ? personalApp.name : 'AI 策略工坊' }}</h1><p class="sw-subtitle">{{ personalAppView ? say('策略已经保存好了。你可以换股票、日期和模拟投入金额，再试一次。', '复用已保存的策略规则与代码，重新配置标的、样本区间与初始资本并回测。') : say('说说你想怎么买卖，我们帮你写清规则，再用过去的数据试一试。', '将投资假设转化为可执行交易规则，并以历史行情检验策略绩效。') }}</p></div>
      <div class="sw-header-actions"><button type="button" class="sw-button" :disabled="busy || loading" data-action="history" @click="viewingHistory ? w.leaveHistory() : w.showHistory()">{{ viewingHistory ? '返回工坊' : '历史记录' }}</button><button type="button" class="sw-button" :disabled="busy || loading" data-action="new-session" @click="startNewSession()">新建</button></div>
    </header>

    <div v-if="!ownerKey" class="sw-card"><h2>登录后使用策略工坊</h2><p>{{ say('你的想法、每一步对话和测试结果，都会保存在这个账号里。', '策略确认记录、回测运行与数据快照按当前账号隔离保存。') }}</p></div>
    <template v-else>
      <ol v-if="!viewingHistory" class="sw-steps" aria-label="回测流程"><li v-for="(label, index) in steps" :key="label" :class="{ current: index === activeStep, done: index < activeStep }" :aria-current="index === activeStep ? 'step' : undefined"><span>{{ index < activeStep ? '✓' : index + 1 }}</span>{{ label }}</li></ol>
      <div v-if="error" class="sw-alert sw-error" role="alert">{{ error }}<button v-if="loading" type="button" @click="w.reload()">重新读取</button></div>
      <div v-if="loading" class="sw-card sw-loading" role="status"><i class="sw-spinner" />正在恢复策略工坊…</div>

      <section v-else-if="historyOpen" class="sw-card">
        <div class="sw-section-heading"><div><h2 data-step-heading tabindex="-1">历史记录</h2><p>{{ say('从最初的想法到最后的结果，每一步都能在这里找回来。还没试跑完的也会保存。', '按会话回溯完整策略研究过程，包括未执行回测的记录。历史内容只读。') }}</p></div><button type="button" class="sw-button" :disabled="Boolean(busy)" @click="w.refreshHistory()">刷新</button></div>
        <p v-if="!history.length" class="sw-empty">还没有策略对话。提交投资想法后，各阶段的分析、补充与确认都会保存在这里。</p>
        <ul v-else class="sw-history"><li v-for="record in history" :key="record.sessionId || record.id"><button type="button" :data-session-id="record.sessionId || record.id" :disabled="Boolean(busy)" @click="w.openHistory(record)"><span><strong>{{ record.idea || '策略会话' }}</strong><span class="sw-muted">{{ record.strategyName || '等待匹配策略' }} · {{ record.runCount || 0 }} 次回测</span><span>查看完整阶段对话</span><small>{{ dateTime(record.updatedAt || record.createdAt) }}</small></span><span class="sw-badge" :class="record.status">{{ sessionStatus(record.status) }}</span></button></li></ul>
        <div v-if="nextCursor" class="sw-actions"><button type="button" class="sw-button" :disabled="Boolean(busy)" @click="w.loadMoreHistory()">加载更多</button></div>
      </section>

      <WorkshopConversation v-else-if="conversationOpen && conversation" :conversation="conversation" :busy="Boolean(busy)" @open-run="w.openHistoricalRun" @open-session="w.openHistory" @back="w.showHistory" />

      <section v-else-if="step === 'idea'" class="sw-card">
        <p class="sw-kicker">{{ say('01 / 说说想法', '01 / 策略假设') }}</p><h2 data-step-heading tabindex="-1">{{ say('你想怎么买、什么时候卖？', '描述你的策略假设') }}</h2><p class="sw-lead">{{ say('像聊天一样说就行。比如：涨得比较稳时买入，开始走弱时卖出。我们会从 10 个现成方案里，找一个最接近你的。', '描述投资逻辑、入场与离场条件。系统从 10 个标准策略模板中匹配最接近的一项。') }}</p>
        <p v-if="sourceRunId" class="sw-alert">已带入历史想法和回测参数。此次会重新匹配、确认与校验，成功后保存为新记录。</p>
        <form data-action="match-form" @submit.prevent="w.match()"><label for="sw-idea">{{ say('说说你的想法', '投资逻辑与交易假设') }}</label><textarea id="sw-idea" v-model="idea" rows="6" maxlength="4000" :placeholder="say('例如：我想在最近的平均价格高于之前一段时间时买入，跌回去就卖出。', '例如：采用趋势跟踪，短期均线上穿长期均线入场，死叉离场。')" :disabled="Boolean(busy)" :aria-invalid="Boolean(fieldErrors.idea)" :aria-describedby="fieldErrors.idea ? 'sw-idea-error' : 'sw-idea-help'" /><p v-if="fieldErrors.idea" id="sw-idea-error" class="sw-field-error">{{ fieldErrors.idea }}</p><p id="sw-idea-help" class="sw-hint">{{ say('我们先解释你的想法，再推荐一个方案。你可以直接试，也可以把它改成自己的规则。', '先完成策略语义匹配与差异说明；可采用标准模板，或基于已有行情字段定制交易规则。') }}</p><div class="sw-actions"><button type="submit" data-action="match" class="sw-button primary" :disabled="Boolean(busy)"><i v-if="busy === 'match'" class="sw-spinner" />{{ busy === 'match' ? say('正在理解你的想法…', '正在匹配并解析策略…') : say('帮我找策略', '匹配量化策略') }}</button></div></form>
      </section>

      <section v-else-if="step === 'recommendation'" class="sw-card">
        <p class="sw-kicker">{{ say('02 / 选好规则', '02 / 规则确认') }}</p>
        <div class="sw-strategy-analysis">
          <h2 data-step-heading tabindex="-1">{{ say('先聊聊你的想法', '投资逻辑解析') }}</h2>
          <p v-if="candidate" class="sw-generated-style">{{ languageStyleLabel(candidate.languageStyle) }} · {{ say('这段回复保留生成时的原话', '保留生成时的原始表达') }}</p><blockquote class="sw-idea-quote">{{ session?.idea }}</blockquote>
          <p v-if="understoodIdea" class="sw-understood-idea">{{ understoodIdea }}</p>
          <p v-else class="sw-hint">这条记录来自旧版匹配，尚未保存对原始策略的分析。你可以重新描述想法，获取新的分析。</p>
          <h3>{{ say('可以怎么做', '策略实现路径') }}</h3>
          <p v-if="implementationApproach" class="sw-implementation-approach">{{ implementationApproach }}</p>
          <p v-else class="sw-hint">这条旧记录尚未保存实现思路分析。你可以重新描述想法，重新匹配。</p>
        </div>
        <div class="sw-template-comparison">
          <p class="sw-kicker">{{ say('这个现成方案和你的想法比较像', '最相近的标准策略模板') }}</p><div class="sw-section-heading"><h3>{{ name }}</h3><span class="sw-badge">固定策略 · {{ version }}</span></div>
          <div v-if="candidate?.fallbackReason || candidate?.intentValidity === 'no_usable_rule'" class="sw-alert"><strong>当前为基础示例</strong><p>{{ fallbackText }}</p></div>
          <p v-else-if="candidate?.quality === 'low'" class="sw-alert">与当前想法匹配较弱。请核对下方规则与差异后决定是否采用。</p>
          <div class="sw-explanation"><h3>{{ say('为什么推荐它', '策略匹配依据') }}</h3><p>{{ rationale || '此策略采用以下固定规则，请核对它是否符合你的想法。' }}</p><h3>{{ say('哪里一样', '一致的交易逻辑') }}</h3><ul v-if="covered.length"><li v-for="(part, index) in covered" :key="index">{{ part }}</li></ul><p v-else>这条记录尚未列明共同点，请结合固定规则核对，不代表已完整实现你的想法。</p><h3>{{ say('哪里不一样，还有什么没做到', '策略差异与未覆盖条件') }}</h3><ul v-if="gaps.length"><li v-for="(gap, index) in gaps" :key="index">{{ gap }}</li></ul><p v-else>只执行下方列明的固定规则，未列出的条件不会自动加入策略。</p><h3>{{ say('这个方案什么时候买、什么时候卖', '模板的入场、离场与持仓规则') }}</h3><ul v-if="rules.length"><li v-for="(rule, index) in rules" :key="index">{{ rule }}</li></ul><p v-else>{{ strategy.summary }}</p></div>
        </div>
        <details class="sw-code" @toggle="openCode"><summary>{{ say('展开看策略代码', '查看标准模板规则与源码') }}</summary><p class="sw-hint">{{ candidate?.strategyId || strategy.key }} · {{ version }} · Python。模块依赖共享 strategy_workshop.models / indicators；需与完整代码包一起使用。</p><dl class="sw-parameters"><template v-for="(value, key) in fixedParameters" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></template></dl><pre tabindex="0"><code>{{ sourceCode || '代码暂不可读取，请重新同步后查看。' }}</code></pre><div class="sw-actions"><span role="status">{{ codeStatus }}</span><button type="button" class="sw-button" :disabled="!sourceCode" @click="copyCode">复制完整代码</button></div></details>
        <div class="sw-strategy-choices">
          <h3>{{ say('接下来，你想怎么试？', '选择策略研究路径') }}</h3>
          <div class="sw-choice-grid">
            <div class="sw-choice"><span class="sw-choice-label">{{ say('选择一 · 按我的想法改', '路径一 · 定制交易规则') }}</span><button type="button" class="sw-button" :disabled="Boolean(busy)" data-action="customize" @click="w.considerCustomization()">{{ say('按我的想法修改', '基于原始假设定制策略') }}</button><p class="sw-hint">{{ say('把不一样的地方改成你想要的。我们先和你核对规则，再检查代码能不能正确运行。', '基于既有行情数据生成规则，确认后编译策略代码并进行一致性与隔离执行校验。') }}</p></div>
            <div class="sw-choice"><span class="sw-choice-label">{{ say('选择二 · 先试这个方案', '路径二 · 回测标准模板') }}</span><button type="button" class="sw-button primary" :disabled="Boolean(busy)" data-action="accept-template" @click="w.select('accept')">{{ busy === 'selection' ? '正在确认…' : selectionAccepted ? say('返回测试设置', '返回回测配置') : say('先试试这个方案', '回测标准策略') }}</button><p class="sw-hint">{{ say('先不修改，试试上面这个方案。接下来选一只股票或 ETF、日期和模拟投入金额。', '采用标准规则，下一步配置回测标的、样本区间与初始资本。') }}</p></div>
          </div>
        </div>
        <div class="sw-actions spread"><button type="button" class="sw-button" :disabled="Boolean(busy)" data-action="reject-template" @click="w.select('reject')">{{ say('重新说说我的想法', '修订策略假设并重新匹配') }}</button></div>
      </section>

      <section v-else-if="step === 'customization'" class="sw-card sw-customization">
        <p class="sw-kicker">{{ say('02 / 修改并确认规则', '02 / 策略定制与校验') }}</p><div class="sw-section-heading"><h2 data-step-heading tabindex="-1">{{ say('把规则改成你想要的', '定制策略规则与代码') }}</h2><span class="sw-badge" :class="customization?.status">{{ customStatus }}</span></div>
        <blockquote class="sw-idea-quote">{{ session?.idea }}</blockquote>
        <p class="sw-hint">以 {{ session?.baseCandidate?.name || name }} {{ say('作为参考，按你说的条件来改。先核对买卖规则，再用过去的数据试试。', '作为基准模板，保留用户明确约束。完成规则编译与验证后，确认采用并配置回测。') }}</p>
        <div v-if="['customization', 'customization-confirm'].includes(busy)" class="sw-alert" role="status"><i class="sw-spinner" /> {{ busy === 'customization-confirm' ? say('正在检查代码是否按规则运行…', '正在生成策略代码并进行隔离校验…') : say('正在把你的要求整理成规则…', '正在解析策略约束与模板差异…') }}</div>
        <p v-if="customization" class="sw-generated-style">{{ languageStyleLabel(customization.languageStyle) }} · {{ say('这段回复保留生成时的原话', '保留生成时的原始表达') }}</p><p v-if="customization?.summary" class="sw-custom-summary">{{ customization.summary }}</p>
        <div v-if="customization?.status === 'unsupported_data'" class="sw-alert" role="status"><strong>{{ say('这个想法还需要我们没有的数据', '策略依赖外源数据') }}</strong><p>本平台暂不支持外源数据，如果你有数据，可以自行上传进行策略开发验证。</p><p class="sw-hint">{{ say('这个版本还没有上传入口。', '当前版本尚未开放外源数据上传入口。') }}</p><ul><li v-for="(gap, index) in customization.dataGaps" :key="index">{{ gap }}</li></ul></div>
        <div v-if="customization?.questions?.length" class="sw-explanation"><h3>{{ say('再告诉我们一点', '待明确的策略条件') }}</h3><ol><li v-for="(question, index) in customization.questions" :key="index">{{ question }}</li></ol></div>
        <template v-if="customization?.rulePlan">
          <h3>{{ say('看看这些买卖规则对不对', '确认本版本交易规则') }}</h3><dl class="sw-facts sw-custom-rules"><template v-for="item in customSummary" :key="item.key"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></template></dl>
          <p class="sw-hint">{{ say('如果买入和卖出条件同时满足，先按卖出来处理。两边都不满足，就保持原来的买卖目标。计算需要的历史数据还不够时先等待；每天收盘后判断，下一交易日开盘再模拟买卖。', '离场条件优先；无入场或离场触发时沿用上一目标状态。指标预热期间不输出有效目标；以收盘数据产生信号，下一交易日开盘模拟成交。') }}</p>
          <div v-if="customization.assumptions?.length" class="sw-alert"><strong>{{ say('没特别说明的地方，先这样处理', '本版本默认参数与建模假设') }}</strong><ul><li v-for="(assumption, index) in customization.assumptions" :key="index">{{ assumption }}</li></ul></div>
          <details class="sw-method"><summary>查看规则版本</summary><dl class="sw-facts"><dt>版本</dt><dd>{{ customization.id }}</dd><dt>规则摘要</dt><dd>{{ customization.rulesDigest }}</dd></dl></details>
        </template>
        <div v-if="customization?.status === 'validation_failed'" class="sw-alert sw-error" role="alert">{{ customizationError }}</div>
        <div v-if="customization?.status === 'validated'" class="sw-custom-validation"><h3>代码校验通过</h3><p class="sw-success">{{ say('代码已经通过检查，可以用这版规则继续了。', '本版本已通过规则一致性与隔离执行校验，可确认采用。') }}</p><p class="sw-hint">{{ say('检查通过，只代表代码按规则做事。过去表现怎么样，还要用历史数据试过才知道。', '校验验证规则表达与执行一致性，不构成绩效评价；需进一步进行历史回测。') }}</p><details class="sw-method"><summary>查看本版验证记录</summary><pre>{{ JSON.stringify(customization.validation, null, 2) }}</pre></details></div>
        <details v-if="customization?.sourceCode" class="sw-code"><summary>查看改写后的策略代码</summary><p class="sw-hint">代码摘要：{{ customization.sourceHash }} · 此代码对应上面展示的规则版本。</p><pre tabindex="0"><code>{{ sourceCode }}</code></pre><div class="sw-actions"><span role="status">{{ codeStatus }}</span><button type="button" class="sw-button" :disabled="!sourceCode" @click="copyCode">复制完整代码</button></div></details>
        <form class="sw-custom-input" @submit.prevent="w.rewriteCustomization()"><label for="sw-custom-instructions">{{ say('还想怎么改？', '补充或修订策略约束') }}</label><textarea id="sw-custom-instructions" v-model="customizationInstructions" rows="3" maxlength="4000" :disabled="Boolean(busy)" :placeholder="say('例如：改成最近10天的平均价格高于最近30天时买入，低于或等于时卖出。', '例如：SMA(10) > SMA(30) 入场，SMA(10) ≤ SMA(30) 清仓。')" /><p class="sw-hint">{{ say('写下要改的地方，我们会重新整理给你确认。目前一次只试一只股票或 ETF，按每天的数据判断，只支持先买后卖、不借钱放大投入。', '补充要求生成新规则版本，并重新进行确认与校验。当前支持日频、单标的、只做多、无杠杆及既有行情字段可表达的条件。') }}</p><div class="sw-actions"><button type="submit" data-action="rewrite-rules" class="sw-button" :disabled="Boolean(busy) || (Boolean(customization) && !customizationInstructions.trim())">{{ busy === 'customization' ? '正在整理…' : customization ? say('按补充内容再改一下', '根据补充约束重新生成规则') : say('再整理一次规则', '重新生成规则') }}</button></div></form>
        <div class="sw-actions spread"><button type="button" class="sw-button" :disabled="Boolean(busy)" @click="w.returnToBaseStrategy()">{{ say('先回到原来的方案', '返回标准策略模板') }}</button><button v-if="customization?.status === 'rules_ready'" type="button" class="sw-button primary" :disabled="Boolean(busy)" data-action="confirm-rules" @click="w.confirmCustomization()">{{ busy === 'customization-confirm' ? '正在校验代码…' : say('规则没问题，检查代码', '确认规则并校验代码') }}</button><button v-if="customization?.status === 'validated'" type="button" class="sw-button primary" :disabled="Boolean(busy)" data-action="accept-custom" @click="w.select('accept')">{{ busy === 'selection' ? '正在确认…' : selectionAccepted ? say('返回测试设置', '返回回测配置') : say('就用这些规则，开始设置', '采用定制策略并配置回测') }}</button></div>
      </section>

      <section v-else-if="step === 'config'" class="sw-card">
        <p class="sw-kicker">{{ say('03 / 用历史数据试试', '03 / 回测配置') }}</p><h2 data-step-heading tabindex="-1">{{ personalAppView ? '回测设置' : say('用过去的数据试一试', '配置历史回测') }}</h2><p class="sw-lead">已确认：<strong>{{ name }}</strong> {{ version }}。{{ say('选一只股票或 ETF、想测试的日期，以及模拟投入多少钱。', '选择回测标的、历史样本区间与初始资本。') }}</p><p v-if="personalAppView" class="sw-hint" data-personal-app-rerun>{{ say('这里沿用这个应用已经保存的买卖规则和代码。改好下面的设置，检查数据后再开始测试。原来的结果会保留。', '沿用个人应用冻结的策略规则与执行代码；重新校验数据、显式确认后发起独立回测，保留原始结果。') }}</p>
        <form @submit.prevent="w.checkConfig()"><div class="sw-form-grid"><div class="sw-field sw-field-wide"><label for="sw-symbol">{{ say('股票或 ETF 代码', '回测标的代码') }}</label><input id="sw-symbol" v-model="form.symbol" list="sw-symbol-options" placeholder="510300.SH" :disabled="Boolean(busy)" :aria-invalid="Boolean(fieldErrors.symbol)" aria-describedby="sw-symbol-help sw-symbol-error" @input="w.searchSymbols($event.target.value)" @change="w.useSymbolDefaults()"><datalist id="sw-symbol-options"><option v-for="item in symbols" :key="item.symbol || item.code" :value="item.symbol || item.code">{{ item.name }} · {{ item.assetType || item.asset_type }}{{ item.supported === false ? ' · 暂不可回测' : '' }}</option></datalist><p id="sw-symbol-help" class="sw-hint">{{ selectedSymbol?.name || '请选择已储备行情的股票或场内 ETF' }}{{ selectedSymbol?.supported === false ? '（尚未完成交易规则审核，暂不可运行）' : '' }} · 数据截至：<strong>{{ selectedSymbol?.asof || preflight?.asof || '待校验' }}</strong></p><p v-if="fieldErrors.symbol" id="sw-symbol-error" class="sw-field-error">{{ fieldErrors.symbol }}</p></div><div class="sw-field"><label for="sw-start">开始日期</label><input id="sw-start" v-model="form.startDate" type="date" :disabled="Boolean(busy)" :aria-invalid="Boolean(fieldErrors.startDate)" aria-describedby="sw-start-error"><p v-if="fieldErrors.startDate" id="sw-start-error" class="sw-field-error">{{ fieldErrors.startDate }}</p></div><div class="sw-field"><label for="sw-end">结束日期</label><input id="sw-end" v-model="form.endDate" type="date" :disabled="Boolean(busy)" :aria-invalid="Boolean(fieldErrors.endDate)" aria-describedby="sw-end-error"><p v-if="fieldErrors.endDate" id="sw-end-error" class="sw-field-error">{{ fieldErrors.endDate }}</p></div><div class="sw-field sw-field-wide"><label for="sw-cash">{{ say('模拟投入多少钱（元）', '初始资本（元）') }}</label><input id="sw-cash" v-model="form.initialCash" type="number" min="0.01" step="0.01" inputmode="decimal" :disabled="Boolean(busy)" :aria-invalid="Boolean(fieldErrors.initialCash)" aria-describedby="sw-cash-error"><p v-if="fieldErrors.initialCash" id="sw-cash-error" class="sw-field-error">{{ fieldErrors.initialCash }}</p></div></div>
          <details class="sw-method"><summary>{{ say('这次怎么模拟买卖、怎么算结果', '交易执行假设与绩效计算口径（只读）') }}</summary><p>{{ say('每天收盘后判断买不买、卖不卖，下一交易日开盘模拟成交。只先买后卖，不借钱。按规定的交易数量和现有资金买入；持有后不会每天调整数量，到最后一天也不会为了结束测试强行卖出。', '日频、只做多、无杠杆；收盘产生信号，下一交易日开盘模拟成交。按最小交易单位买入可支付数量，持仓期间不进行每日再平衡；期末不强制平仓。') }}</p><p>{{ say('每笔买卖收万分之三手续费，最低 5 元；另把买价调高、卖价调低各 0.05%，模拟实际成交价差（滑点）。股票还计过户费和卖出印花税，ETF 这两项设为 0。不计算个人股息税。一年按 252 个交易日折算，无风险利率设为 0。', '佣金率 3 bps，单笔最低 5 元；双边滑点各 5 bps。股票另计过户费及卖出印花税，ETF 两项参考配置为 0。未模拟个人股息税。年化因子为 252，无风险利率为 0。') }}</p><p>{{ say('对照方案是买入同一只股票或 ETF 后一直持有（基准），日期和费用相同。先用一段数据准备计算（预热），这段不算收益。停牌、涨跌停、买后何时能卖以及分红拆股等数据还需要核实；数据不完整时只能试跑，不能出正式收益报告。', '基准为同标的买入并持有，使用同一费用模型与评估区间。预热区间仅生成信号，不计入绩效。须核验停牌、价格限制、结算约束及企业行为数据；不满足数据门槛时仅提供工程诊断回测。') }}</p></details>
          <div class="sw-actions spread"><button v-if="personalAppView" type="button" class="sw-button" data-action="previous-personal-app-result" :disabled="Boolean(busy) || !run" @click="w.viewPersonalAppResult()">查看上次回测结果</button><button v-else type="button" class="sw-button" :disabled="Boolean(busy)" @click="viewConfirmedStrategy">{{ say('再看看选好的规则', '查看已确认策略') }}</button><button type="submit" data-action="preflight" class="sw-button" :disabled="Boolean(busy)">{{ busy === 'preflight' ? say('正在检查数据…', '正在校验数据…') : preflight ? say('再检查一次数据', '重新校验数据') : say('检查这些日期有没有数据', '校验数据与区间') }}</button></div></form>
        <div v-if="preflight" class="sw-preflight"><h3>{{ say('数据检查结果', '数据质量与样本覆盖校验') }}</h3><dl class="sw-facts"><dt>数据截至</dt><dd>{{ preflight.asof }}</dd><dt>{{ say('你选的日期', '请求回测区间') }}</dt><dd>{{ interval(preflight.requested) }}</dd><dt>{{ say('实际能测试的日期', '实际可运行区间') }}</dt><dd>{{ interval(preflight.actual) }}</dd><dt>{{ say('股票或 ETF', '回测标的') }}</dt><dd>{{ preflight.instrument?.name }} {{ preflight.instrument?.symbol || preflight.instrument?.code || form.symbol }}</dd></dl>
          <div v-if="coverageRequired" class="sw-alert"><strong>{{ say('实际能测试的日期和你选的不一样', '样本覆盖与请求区间不一致') }}</strong><ul><li v-for="(reason, index) in coverageReasons" :key="index">{{ reason }}</li></ul><label class="sw-check"><input v-model="coverageAccepted" type="checkbox" :disabled="Boolean(busy)"><span>{{ say('我同意用上面实际能测试的日期，并把它保存在这次记录里。', '确认采用上述实际可运行区间，并冻结至本次运行记录。') }}</span></label></div>
          <div v-if="!formalAvailable" class="sw-alert"><strong>正式报告暂不可用</strong><p>{{ say('有些必要的数据还不完整，所以目前只能先试跑。', '当前数据未满足完整金融收益报告的数据门槛。') }}</p><ul v-if="missingData.length"><li v-for="(reason, index) in missingData" :key="index">{{ reason }}</li></ul><label class="sw-check"><input v-model="diagnosticAccepted" type="checkbox" :disabled="Boolean(busy)"><span>{{ say('我已了解缺少哪些数据，同意先试跑。下面的数字和图只用于检查策略，不能当成完整收益报告。', '确认上述数据缺口，并选择工程诊断回测。绩效指标与曲线不构成完整收益报告。') }}</span></label></div>
          <p v-else class="sw-success">本次冻结数据已通过正式报告校验。</p><ul v-if="preflight.warnings?.length" class="sw-hint"><li v-for="(warning, index) in preflight.warnings" :key="index">{{ warning }}</li></ul><div class="sw-actions"><button type="button" class="sw-button primary" :disabled="!canRun" data-action="run" @click="w.startRun()">{{ busy === 'run' ? '正在提交…' : formalAvailable ? say('开始测试', '开始回测') : say('先试跑看看', '开始工程诊断回测') }}</button></div>
        </div>
      </section>

      <section v-else-if="step === 'result'" class="sw-result">
        <div v-if="canReconfigurePersonalApp" class="sw-card sw-personal-rerun"><div><h2>{{ say('换一组设置，再试一次', '复用策略重新回测') }}</h2><p class="sw-hint">{{ say('继续用这个应用的买卖规则，重新选择股票或 ETF、日期和模拟投入金额。', '保持策略规则与代码不变，重新配置标的、回测区间及初始资本。') }}</p></div><button type="button" class="sw-button primary" data-action="rerun-personal-app" :disabled="Boolean(busy)" @click="w.reconfigurePersonalApp()"><i v-if="busy === 'personal-app-session'" class="sw-spinner" />{{ busy === 'personal-app-session' ? '正在载入回测设置…' : '重新设置并回测' }}</button></div>
        <div class="sw-actions sw-history-result-actions"><span v-if="historyReadOnly" class="sw-hint">{{ personalAppView ? '正在查看已保存的个人策略应用。' : '正在查看历史回测，当前编辑内容已保留。' }}</span><button type="button" class="sw-button" :disabled="Boolean(busy)" @click="w.viewRunConversation()">查看本次完整对话</button></div>
        <div class="sw-card"><div class="sw-section-heading"><div><p class="sw-kicker">{{ say('04 / 看看结果', '04 / 绩效评估') }} <span v-if="historyReadOnly">· 历史记录，只读</span></p><h2 data-step-heading tabindex="-1">{{ statusLabel(run?.status) }}</h2></div><span class="sw-badge" :class="run?.status">{{ diagnostic ? say('先试跑', '工程诊断') : say('历史数据测试', '历史回测') }}</span></div><p class="sw-lead">{{ report?.strategy?.name || run?.strategy?.name || name }} {{ report?.strategy?.version || run?.strategy?.version }} · {{ run?.requested?.symbol || report?.instrument?.symbol }} · {{ interval(run?.actual || report?.actual_interval) }}</p><p class="sw-hint">运行 ID：{{ run?.runId }} · {{ dateTime(run?.createdAt) }}</p>
          <div v-if="diagnostic" class="sw-alert"><strong>{{ say('这是试跑结果，不是正式收益报告', '工程诊断结果，非正式收益报告') }}</strong><p>{{ say('这次在你确认数据缺口后先试跑。分红、分红后的价格调整、哪些日子能交易、订单能否成交等数据还没完全核实，会影响下面的结果。', '本次基于已确认的数据缺口执行工程验证。未核验的企业行为、复权、交易日历及可成交状态会影响绩效结果。') }}</p></div>
          <div v-if="syncError" class="sw-alert sw-error" role="alert">{{ syncError }}<button type="button" class="sw-button" @click="w.syncRun()">重新同步</button></div>
          <div v-if="active" class="sw-running" role="status"><i class="sw-spinner" /><div><strong>{{ phase }}</strong><p>运行由服务端处理。离开页面后可能继续，刷新可以恢复观察。</p></div><button v-if="!historyReadOnly" type="button" class="sw-button" :disabled="busy || ['cancelling', 'cancel_requested'].includes(run.status)" @click="w.cancelRun()">{{ ['cancelling', 'cancel_requested'].includes(run.status) ? '正在停止…' : '取消本次回测' }}</button></div>
          <div v-else-if="!isFinishedRun(run)" class="sw-empty"><p v-if="run?.status === 'failed'" class="sw-field-error">{{ runError }}</p><p v-else-if="run?.status === 'interrupted'">上次运行已中断，需要重新发起。</p><p v-else-if="run?.status === 'cancelled'">执行侧已确认停止，本次没有完整收益报告。</p><p v-else>尚无完整结果，请重新同步运行状态。</p><div class="sw-actions"><button v-if="!historyReadOnly" type="button" class="sw-button" @click="backToParameters">返回参数，重新校验</button><button v-else type="button" class="sw-button" :disabled="Boolean(busy)" @click="startNewSession({ fromRun: true })">用这些参数新建回测</button></div></div>
          <p v-if="isFinishedRun(run) && !report" class="sw-alert sw-error" role="alert">运行状态已完成，但结果快照暂不可读取，请重新同步后查看。</p><template v-if="report && isFinishedRun(run)"><dl class="sw-facts"><dt>数据截至</dt><dd><strong>{{ asof }}</strong></dd><dt>{{ say('你选的日期', '请求回测区间') }}</dt><dd>{{ interval(run?.requested) }}</dd><dt>{{ say('实际能测试的日期', '实际可运行区间') }}</dt><dd>{{ interval(run?.actual || report.actual_interval) }}</dd><dt>{{ say('一开始投入', '初始资本') }}</dt><dd>{{ money(report.config?.initial_cash) }}</dd><dt>{{ say('用了多少天数据', '有效样本长度') }}</dt><dd>{{ report.actual_interval?.trading_days }} {{ say('个交易日 · 另外先用', '个交易日 · 指标预热') }} {{ report.actual_interval?.warmup_bars }} {{ say('天数据准备计算', '根日线') }}</dd></dl><div class="sw-metrics"><article v-for="metric in metrics" :key="metric.key"><h3>{{ metric.label }}</h3><strong>{{ metric.value }}</strong><p>{{ metric.hint }}</p><details v-if="metric.reason"><summary>无法计算的原因</summary><p>{{ metric.reason }}</p></details></article></div></template>
        </div>
        <template v-if="report && isFinishedRun(run)"><WorkshopChart :strategy="report.strategy_result?.equity_curve" :benchmark="report.benchmark_result?.equity_curve" :diagnostic="diagnostic" /><WorkshopChart :strategy="report.strategy_result?.equity_curve" :benchmark="report.benchmark_result?.equity_curve" field="drawdown" :diagnostic="diagnostic" />
          <div class="sw-card"><h3>{{ say('买卖记录和最后还持有多少', '成交明细与期末持仓') }}</h3><p class="sw-hint">{{ say('到最后一天不会自动把持有的全部卖掉。还没卖出的部分，按当天收盘价算进收益。买入后又全部卖出，才会计入交易次数和胜率。', '期末不强制平仓，未平仓头寸按收盘价估值计入净值；交易次数与胜率仅统计已平仓完整往返。') }}</p><dl v-if="position" class="sw-facts"><dt>{{ say('还持有多少', '期末持仓数量') }}</dt><dd>{{ number(position.quantity, 0) }}</dd><dt>{{ say('最后一天值多少钱', '期末持仓市值') }}</dt><dd>{{ money(position.market_value) }}</dd><dt>{{ say('还没卖出部分的赚亏', '未实现盈亏') }}</dt><dd>{{ money(position.unrealized_pnl) }}</dd><dt>{{ say('应收但还没到账的分红', '应收股息') }}</dt><dd>{{ money(report.strategy_result?.dividend_receivable) }}</dd></dl>
            <details class="sw-table-details"><summary>成交记录（{{ fills.length }} 条）</summary><p v-if="!fills.length" class="sw-empty">本区间没有成交。</p><div v-else class="sw-table-wrap"><table><caption>策略成交记录</caption><thead><tr><th scope="col">日期</th><th scope="col">信号日期</th><th scope="col">方向</th><th scope="col">数量</th><th scope="col">成交价</th><th scope="col">金额</th></tr></thead><tbody><tr v-for="(fill, index) in fills" :key="index"><td>{{ fill.date }}</td><td>{{ fill.signal_date || '—' }}</td><td>{{ fill.side === 'buy' ? '买入' : '卖出' }}</td><td>{{ number(fill.quantity, 0) }}</td><td>{{ number(fill.price, 3) }}</td><td>{{ money(fill.notional) }}</td></tr></tbody></table></div></details>
            <details class="sw-table-details"><summary>{{ say('买入后又卖出的记录', '已平仓完整往返') }}（{{ trades.length }} 次）</summary><p v-if="!trades.length" class="sw-empty">{{ say('还没有买入后又全部卖出的交易，所以暂时算不了胜率。', '尚无已平仓完整往返，胜率不可计算。') }}</p><div v-else class="sw-table-wrap"><table><caption>扣除成本的已平仓往返</caption><thead><tr><th scope="col">买入日期</th><th scope="col">卖出日期</th><th scope="col">净利润</th></tr></thead><tbody><tr v-for="(trade, index) in trades" :key="index"><td>{{ trade.entry_date }}</td><td>{{ trade.exit_date }}</td><td>{{ money(trade.net_pnl) }}</td></tr></tbody></table></div></details>
            <details v-if="rejectedOrders.length" class="sw-table-details"><summary>未成交记录（{{ rejectedOrders.length }} 条）</summary><div class="sw-table-wrap"><table><caption>未成交的模拟订单及原因</caption><thead><tr><th scope="col">日期</th><th scope="col">方向</th><th scope="col">原因</th></tr></thead><tbody><tr v-for="(order, index) in rejectedOrders" :key="index"><td>{{ order.date }}</td><td>{{ order.side === 'buy' ? '买入' : '卖出' }}</td><td>{{ rejectReason(order.reason) }}</td></tr></tbody></table></div></details>
          </div>
        </template>
        <div class="sw-card"><details v-if="customRun" class="sw-method sw-custom-run-evidence"><summary>本次自定义规则与验证</summary><dl class="sw-facts"><dt>规则版本</dt><dd>{{ customRunEvidence.customization_id || run?.candidate?.customizationId }}</dd><dt>规则摘要</dt><dd>{{ customRunEvidence.rules_digest || run?.candidate?.rulesDigest }}</dd><dt>代码摘要</dt><dd>{{ customRunEvidence.source_sha256 || run?.candidate?.sourceHash }}</dd><dt>买入条件</dt><dd>{{ customRunRules.entry }}</dd><dt>退出条件</dt><dd>{{ customRunRules.exit }}</dd></dl><p v-if="customRunEvidence.validation?.passed" class="sw-success">本次冻结版本已通过规则与代码校验。</p><p v-else class="sw-hint">验证记录将在本次运行完成后展示。</p><pre v-if="customRunEvidence.validation">{{ JSON.stringify(customRunTrace, null, 2) }}</pre></details><details class="sw-method"><summary>本次参数、数据与版本</summary><p class="sw-hint">原始想法：{{ runIdea }}</p><pre>{{ JSON.stringify({ requested: run?.requested, actual: run?.actual, gate: run?.gate, config: report?.config, instrument: report?.instrument, engineVersion: report?.engine_version, implementationHash: report?.implementation_sha256, dataHash: report?.data_snapshot_sha256 }, null, 2) }}</pre><ul v-if="warnings.length" class="sw-hint"><li v-for="(warning, index) in warnings" :key="index">{{ warning }}</li></ul></details><details class="sw-code" @toggle="openCode"><summary>{{ customRun ? '本次自定义策略规则与执行代码' : '本次固定策略规则与执行代码' }}</summary><p class="sw-hint">代码读取自本次运行快照。模块需依赖共享 models / indicators 代码包。{{ customRun ? '自定义代码通过隔离运行产生目标信号。' : '' }}</p><pre tabindex="0"><code>{{ sourceCode || (busy === 'code' ? '正在读取代码快照…' : '展开后读取本次代码快照。') }}</code></pre><div class="sw-actions"><span role="status">{{ codeStatus }}</span><button type="button" class="sw-button" :disabled="!sourceCode" @click="copyCode">复制完整代码</button></div></details><p v-if="personalAppSaveError" class="sw-field-error" role="alert">添加失败：{{ personalAppSaveError }} 请点击下方按钮重试。</p><div v-if="!active" class="sw-actions sw-save-personal-app"><button type="button" class="sw-button primary" data-action="save-personal-app" :disabled="Boolean(busy) || !canSavePersonalApp" @click="addPersonalApp"><i v-if="busy === 'save-personal-app'" class="sw-spinner" />{{ busy === 'save-personal-app' ? '正在添加…' : personalApp ? '已添加 · 在应用中查看' : '添加到我的个人应用' }}</button></div></div>
      </section>
      <p class="sw-footer">{{ say('用过去的数据试一试，只能了解过去的表现。日期、数据和模拟买卖方式都会影响结果。', '历史回测用于检验交易规则；绩效受样本选择、数据质量及执行假设影响。') }}</p>
    </template>
  </div>
</template>

